package controlapi

import "net/http"

// AdminConsole serves the account-scoped operations console. The shell is
// public so operators can reach the login form; every data request remains
// protected by the same access-token and server-side session checks as clients.
func (h *Handler) AdminConsole(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("X-Frame-Options", "DENY")
	_, _ = w.Write([]byte(adminHTML))
}

const adminHTML = `<!doctype html>
<html lang="zh-CN">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Share Disk 控制台</title>
<style>
:root{--bg:#f4f7f5;--surface:#fff;--ink:#15231c;--muted:#6b7971;--line:#e1e8e3;--brand:#126b4e;--brand2:#0c503b;--mint:#dff4e9;--danger:#b33b31;--shadow:0 18px 50px rgba(22,55,39,.09)}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 88% 4%,#dff4e9 0,transparent 27%),var(--bg);color:var(--ink);font:14px/1.5 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}.shell{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{position:sticky;top:0;height:100vh;padding:28px 20px;background:#10281e;color:#fff}.brand{display:flex;align-items:center;gap:12px;margin:0 8px 34px}.logo{display:grid;place-items:center;width:42px;height:42px;border-radius:14px;background:#47d597;color:#0c3827;font-size:21px;font-weight:900}.brand b{display:block;font-size:17px}.brand small{color:#a9c5b8}.nav{display:grid;gap:7px}.nav button{width:100%;border:0;border-radius:12px;padding:12px 14px;background:transparent;color:#bdd0c7;text-align:left;font:inherit;cursor:pointer}.nav button.active,.nav button:hover{background:#254437;color:#fff}.side-foot{position:absolute;left:28px;right:28px;bottom:24px;color:#91aa9f;font-size:12px}.main{padding:34px 38px 60px;min-width:0}.top{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:26px}.top h1{margin:0;font-size:29px;letter-spacing:-.7px}.top p{margin:4px 0 0;color:var(--muted)}.actions{display:flex;gap:8px}.btn{border:0;border-radius:12px;padding:11px 15px;background:var(--mint);color:var(--brand2);font-weight:700;cursor:pointer}.btn.primary{background:var(--brand);color:#fff}.btn.danger{color:var(--danger);background:#fae9e7}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:24px}.metric,.panel{background:rgba(255,255,255,.9);border:1px solid rgba(225,232,227,.9);box-shadow:var(--shadow)}.metric{padding:19px;border-radius:18px}.metric small{color:var(--muted)}.metric strong{display:block;margin-top:7px;font-size:28px;letter-spacing:-1px}.panel{display:none;border-radius:20px;overflow:hidden}.panel.active{display:block}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:19px 21px;border-bottom:1px solid var(--line)}.panel-head h2{margin:0;font-size:18px}.search,input{width:100%;border:1px solid var(--line);border-radius:12px;background:#f9fbfa;color:var(--ink);padding:11px 13px;outline:none}.search{max-width:300px}.search:focus,input:focus{border-color:#73b79a;box-shadow:0 0 0 3px rgba(71,213,151,.15)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{padding:14px 21px;border-bottom:1px solid var(--line);text-align:left}th{color:var(--muted);font-size:12px;font-weight:700;text-transform:uppercase}tbody tr:hover{background:#f7faf8}.name{font-weight:750}.sub{display:block;color:var(--muted);font-size:12px}.pill{display:inline-flex;align-items:center;gap:6px;border-radius:999px;padding:5px 9px;background:var(--mint);color:var(--brand2);font-size:12px;font-weight:700}.pill.off{background:#f1f2f1;color:#69736d}.dot{width:7px;height:7px;border-radius:50%;background:#27ad74}.security{display:grid;grid-template-columns:1fr 1fr;gap:18px;padding:22px}.card{padding:20px;border:1px solid var(--line);border-radius:16px;background:#fbfdfc}.card h3{margin:0 0 6px}.card p{color:var(--muted);margin:0 0 18px}.form{display:grid;gap:10px}.empty{padding:50px;text-align:center;color:var(--muted)}.toast{position:fixed;right:24px;bottom:24px;max-width:360px;border-radius:13px;padding:13px 16px;background:#14261e;color:#fff;box-shadow:var(--shadow);opacity:0;transform:translateY(12px);pointer-events:none;transition:.2s}.toast.show{opacity:1;transform:none}.login{position:fixed;inset:0;z-index:10;display:grid;place-items:center;padding:20px;background:rgba(9,27,19,.75);backdrop-filter:blur(12px)}.login.hidden{display:none}.login-card{width:min(430px,100%);padding:30px;border-radius:24px;background:#fff;box-shadow:0 30px 90px rgba(0,0,0,.28)}.login-card .logo{margin-bottom:20px}.login-card h2{margin:0;font-size:26px}.login-card p{margin:7px 0 22px;color:var(--muted)}.login-card form{display:grid;gap:12px}.login-card .btn{margin-top:4px;padding:13px}.error{min-height:20px;color:var(--danger);font-size:13px}.mobile-menu{display:none}
@media(max-width:900px){.shell{display:block}.side{position:relative;height:auto;padding:16px}.brand{margin:0}.nav{display:flex;overflow:auto;margin-top:14px}.nav button{width:auto;white-space:nowrap}.side-foot{display:none}.main{padding:22px 16px 44px}.grid{grid-template-columns:repeat(2,1fr)}.security{grid-template-columns:1fr}.top{align-items:flex-start}.top h1{font-size:25px}}
@media(max-width:520px){.grid{grid-template-columns:1fr 1fr;gap:9px}.metric{padding:14px}.metric strong{font-size:23px}.actions .btn:not(.primary){display:none}.panel-head{align-items:flex-start;flex-direction:column}.search{max-width:none}.security{padding:14px}.top p{font-size:12px}}
</style></head>
<body>
<div class="shell">
 <aside class="side"><div class="brand"><span class="logo">S</span><div><b>Share Disk</b><small>Operations Console</small></div></div>
  <nav class="nav"><button class="active" data-tab="files">文件消息</button><button data-tab="devices">设备连接</button><button data-tab="account">账号与安全</button></nav>
  <div class="side-foot"><span class="pill"><span class="dot"></span>控制服务已连接</span></div>
 </aside>
 <main class="main">
  <header class="top"><div><h1 id="pageTitle">文件消息</h1><p id="subtitle">统一目录、存储状态与来源设备</p></div><div class="actions"><button class="btn" id="refresh">刷新</button><button class="btn primary" id="logout">退出</button></div></header>
  <section class="grid"><article class="metric"><small>文件总数</small><strong id="fileCount">—</strong></article><article class="metric"><small>总容量</small><strong id="totalSize">—</strong></article><article class="metric"><small>在线设备</small><strong id="onlineCount">—</strong></article><article class="metric"><small>传输任务</small><strong id="transferCount">—</strong></article></section>
  <section class="panel active" id="files"><div class="panel-head"><h2>所有文件消息</h2><input class="search" id="fileSearch" placeholder="搜索名称、类型、Hash"></div><div class="table-wrap"><table><thead><tr><th>文件</th><th>大小</th><th>状态</th><th>来源设备</th><th>更新时间</th></tr></thead><tbody id="fileRows"></tbody></table><div class="empty" id="fileEmpty">暂无文件</div></div></section>
  <section class="panel" id="devices"><div class="panel-head"><h2>设备连接情况</h2><span class="sub">最近 2 分钟心跳视为在线</span></div><div class="table-wrap"><table><thead><tr><th>设备</th><th>平台</th><th>连接状态</th><th>最后心跳</th><th>操作</th></tr></thead><tbody id="deviceRows"></tbody></table><div class="empty" id="deviceEmpty">暂无设备</div></div></section>
  <section class="panel" id="account"><div class="panel-head"><h2>账号与安全</h2></div><div class="security"><article class="card"><h3>账号信息</h3><p>当前控制台只展示已登录账号的数据。</p><div id="accountInfo">加载中…</div></article><article class="card"><h3>修改密码</h3><p>修改后其他设备会话将失效，需要重新登录。</p><form class="form" id="passwordForm"><input id="currentPassword" type="password" autocomplete="current-password" placeholder="当前密码" required><input id="newPassword" type="password" autocomplete="new-password" minlength="8" placeholder="新密码（至少 8 位）" required><input id="confirmPassword" type="password" autocomplete="new-password" minlength="8" placeholder="再次输入新密码" required><button class="btn primary" type="submit">更新密码</button></form></article></div></section>
 </main>
</div>
<div class="login" id="login"><div class="login-card"><div class="logo">S</div><h2>欢迎回来</h2><p>登录 Share Disk 管理监控台</p><form id="loginForm"><input id="accountName" autocomplete="username" placeholder="账号" required><input id="accountPassword" type="password" autocomplete="current-password" placeholder="密码" required><button class="btn primary" type="submit">安全登录</button><div class="error" id="loginError"></div></form></div></div>
<div class="toast" id="toast"></div>
<script>
const $=s=>document.querySelector(s), $$=s=>document.querySelectorAll(s); let token=sessionStorage.getItem('sd_token')||'', files=[], devices=[];
const esc=v=>String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtSize=n=>{n=Number(n||0);if(n<1024)return n+' B';const u=['KB','MB','GB','TB'];let i=-1;do{n/=1024;i++}while(n>=1024&&i<u.length-1);return n.toFixed(n<10?1:0)+' '+u[i]};
const fmtTime=v=>v?new Date(v).toLocaleString('zh-CN'):'尚无心跳';
const isOnline=d=>d.status==='active'&&d.last_seen_at&&(Date.now()-new Date(d.last_seen_at).getTime()<120000);
function notify(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
async function api(path,opt={}){opt.headers=Object.assign({'Content-Type':'application/json','Authorization':'Bearer '+token},opt.headers||{});const r=await fetch(path,opt);if(r.status===401){logout();throw Error('会话已失效，请重新登录')}if(!r.ok){let e={};try{e=await r.json()}catch(_e){}throw Error((e.error&&e.error.message)||e.message||('请求失败 '+r.status))}return r.status===204?{}:r.json()}
function logout(){token='';sessionStorage.removeItem('sd_token');$('#login').classList.remove('hidden')}
function renderFiles(){const q=$('#fileSearch').value.toLowerCase();const shown=files.filter(f=>(f.name+' '+f.mime+' '+f.sha256).toLowerCase().includes(q));$('#fileRows').innerHTML=shown.map(f=>'<tr><td><span class="name">'+esc(f.name)+'</span><span class="sub">'+esc((f.mime||'未知类型')+' · '+(f.sha256||'').slice(0,16))+'…</span></td><td>'+fmtSize(f.size)+'</td><td><span class="pill">'+esc(f.status)+'</span></td><td>'+esc(f.origin_device_name||'未知设备')+'</td><td>'+fmtTime(f.updated_at)+'</td></tr>').join('');$('#fileEmpty').style.display=shown.length?'none':'block'}
function renderDevices(){const current=sessionStorage.getItem('sd_device');$('#deviceRows').innerHTML=devices.map(d=>{const online=isOnline(d);return '<tr><td><span class="name">'+esc(d.name)+'</span><span class="sub">'+esc(d.id.slice(0,12))+'</span></td><td>'+esc(d.platform)+'</td><td><span class="pill '+(online?'':'off')+'"><span class="dot"></span>'+(online?'在线':'离线')+'</span></td><td>'+fmtTime(d.last_seen_at)+'</td><td>'+(d.id===current?'当前设备':'<button class="btn danger" data-remove="'+esc(d.id)+'">撤销</button>')+'</td></tr>'}).join('');$('#deviceEmpty').style.display=devices.length?'none':'block';$$('[data-remove]').forEach(b=>b.onclick=async()=>{if(!confirm('撤销该设备及其全部会话？'))return;try{await api('/v1/devices/'+encodeURIComponent(b.dataset.remove),{method:'DELETE'});notify('设备已撤销');load()}catch(e){notify(e.message)}})}
async function load(){try{const [f,t,d,tr,a]=await Promise.all([api('/v1/catalog/files'),api('/v1/catalog/trash'),api('/v1/devices'),api('/v1/transfers/'),api('/v1/account')]);files=[...(f.files||[]),...(t.files||[])];devices=d.devices||[];const transfers=tr.transfers||[];$('#fileCount').textContent=files.length;$('#totalSize').textContent=fmtSize(files.reduce((s,x)=>s+Number(x.size||0),0));$('#onlineCount').textContent=devices.filter(isOnline).length+'/'+devices.length;$('#transferCount').textContent=transfers.filter(x=>!['completed','canceled','failed_permanent'].includes(x.state)).length;$('#accountInfo').innerHTML='<p><b>'+esc(a.account.account)+'</b><br><span class="sub">状态：'+esc(a.account.status)+'<br>创建：'+fmtTime(a.account.created_at)+'</span></p>';renderFiles();renderDevices()}catch(e){notify(e.message)}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginError').textContent='';let peer=localStorage.getItem('sd_admin_peer');if(!peer){peer='web-'+crypto.randomUUID();localStorage.setItem('sd_admin_peer',peer)}try{const r=await fetch('/v1/auth/enroll',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({account:$('#accountName').value,password:$('#accountPassword').value,name:'Web 管理控制台',platform:'web',peer_id:peer})});const data=await r.json();if(!r.ok)throw Error((data.error&&data.error.message)||data.message||'账号或密码错误');token=data.access_token;sessionStorage.setItem('sd_token',token);sessionStorage.setItem('sd_device',data.device_id);$('#accountPassword').value='';$('#login').classList.add('hidden');load()}catch(err){$('#loginError').textContent=err.message}};
$('#passwordForm').onsubmit=async e=>{e.preventDefault();if($('#newPassword').value!==$('#confirmPassword').value){notify('两次新密码不一致');return}try{await api('/v1/account/password',{method:'PATCH',body:JSON.stringify({current_password:$('#currentPassword').value,new_password:$('#newPassword').value})});e.target.reset();notify('密码已更新，其他设备需重新登录')}catch(err){notify(err.message)}};
$$('.nav button').forEach(b=>b.onclick=()=>{$$('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('.panel').forEach(x=>x.classList.remove('active'));$('#'+b.dataset.tab).classList.add('active');const text={files:['文件消息','统一目录、存储状态与来源设备'],devices:['设备连接','在线状态、最后心跳与会话撤销'],account:['账号与安全','账号信息和密码安全管理']}[b.dataset.tab];$('#pageTitle').textContent=text[0];$('#subtitle').textContent=text[1]});
$('#fileSearch').oninput=renderFiles;$('#refresh').onclick=load;$('#logout').onclick=logout;if(token){$('#login').classList.add('hidden');load()}
</script></body></html>`
